cwdIfUpChannelRangBackoffStart = MibTableColumn((1, 3, 6, 1, 4, 1, 9, 9, 167, 1, 1, 4, 1, 9), Integer32().subtype(subtypeSpec=ValueRangeConstraint(0, 16))).setMaxAccess("readwrite")
